#!/usr/bin/env python3
"""Machine-local final matrix; every case is a fresh, isolated process."""
from pathlib import Path
import argparse,json,os,subprocess,time
p=argparse.ArgumentParser();p.add_argument('engine',choices=['cpu','cuda']);p.add_argument('--rounds',type=int,default=3);p.add_argument('--repeats',type=int,default=6);a=p.parse_args()
root=Path.cwd();base=root/'.validation/paligemma-pi05-20261113';out=base/'optimization/final'

def dirs(model):
 text=(f'{model}-fp32-native-fused-tied' if model=='paligemma' else f'{model}-fp32-native-fused') if a.engine=='cpu' else (f'{model}-fp16-native' if model=='paligemma' else f'{model}-fp16-native-fused')
 return [base/'models'/text,base/'models'/f'{model}-vision-native']

def cache_weights(model):
 files=set()
 for directory in dirs(model):
  cfg=json.loads((directory/'nntr_config.json').read_text())
  for key in ['model_file_name','embedding_bin_path','expert_file_name']:
   if key in cfg:
    path=Path(cfg[key]);files.add(path if path.is_absolute() else directory/path)
 if model=='paligemma':files.update(Path('/home/seungbaek/Downloads/paligemma').glob('*.safetensors'))
 else:files.add(Path('/home/seungbaek/pi05-base-hf/model.safetensors'))
 total=0;start=time.monotonic()
 for path in sorted(files):
  with path.open('rb') as f:
   while chunk:=f.read(16*1024*1024):total+=len(chunk)
 print(f'[cache] {model} bytes={total} elapsed={time.monotonic()-start:.3f}',flush=True)
 return [str(path) for path in sorted(files)]

for model in ['paligemma','pi05']:
 cache_files=cache_weights(model)
 for round_ in range(a.rounds):
  for framework in (['nntrainer','pytorch'] if round_%2==0 else ['pytorch','nntrainer']):
   env=os.environ.copy()
   for k in ['LD_PRELOAD','OMP_PROC_BIND','OMP_PLACES','MKL_VERBOSE','NNTR_VALIDATE_ALTERNATE_REFERENCE','NNTR_PI05_PREFIX_HOST','NNTR_MKL_VECTOR_THREADS']:
    env.pop(k,None)
   threads='8' if a.engine=='cpu' else '4'
   env.update(LD_LIBRARY_PATH=str(base/'mkl-runtime/lib')+':/home/seungbaek/cuda-toolkit/lib64',MKL_THREADING_LAYER=('INTEL' if a.engine=='cpu' and framework=='nntrainer' else 'GNU'),MKL_NUM_THREADS=threads,MKL_DYNAMIC='FALSE',NNTR_CPU_AFFINITY='0',NNTR_BENCH_REPEATS=str(a.repeats),PYTORCH_ALLOC_CONF='expandable_segments:True',NNTR_CUDA_DECODE_GRAPH='1',NNTR_CUDA_PREFETCH_WEIGHTS='1',NNTR_CUBLAS_PEDANTIC='1')
   if a.engine=='cpu':env.update(NNTR_CPU_SHARED_OMP='1',NNTR_CPU_HUGE_PAGES='1',THP_MEM_ALLOC_ENABLE='1',OMP_WAIT_POLICY='ACTIVE',KMP_AFFINITY='disabled',KMP_BLOCKTIME='20',GOMP_SPINCOUNT='100000')
   name=f'{model}-{a.engine}-{framework}-r{round_+1}'
   ref=base/'results/references'/('paligemma-pil-reference' if model=='paligemma' and a.engine=='cpu' else 'paligemma-pytorch-cuda-reference' if model=='paligemma' else 'pi05-reference-fp32')
   cmd=(['taskset','-c','0,2,4,6,8,10,12,14'] if a.engine=='cpu' else [])+['python3','tools/validate_vla_ports.py','--out-dir',str(out),'--threads',threads,'--cuda-async',('1' if a.engine=='cuda' else '0'),name,a.engine]
   if framework=='nntrainer':cmd += [f'build_cuda/Applications/CausalLM/nntr_{model}_e2e',*[str(d) for d in dirs(model)],str(ref)]
   else:
    python=('/home/seungbaek/projects/vllm/.venv/bin/python' if model=='paligemma' else '/home/seungbaek/venvs-openpi/bin/python' if a.engine=='cpu' else str(base/'pytorch-cuda-env/bin/python'))
    cmd += [python,'--','tools/benchmark_vla_pytorch.py',model,a.engine,'--weights',('/home/seungbaek/Downloads/paligemma' if model=='paligemma' else '/home/seungbaek/pi05-base-hf/model.safetensors'),'--reference',str(ref),'--threads',threads,'--repeats',str(a.repeats)]
   # Preserve the complete launcher, affinity and environment for reproduction.
   (out/f'{name}-launcher.json').write_text(json.dumps(dict(command=cmd,environment={k:v for k,v in env.items() if k.startswith(('NNTR_','MKL_','OMP_','KMP_','GOMP_','THP_','PYTORCH_')) or k=='LD_LIBRARY_PATH'},cache_files=cache_files),indent=2)+'\n')
   r=subprocess.run(cmd,env=env,text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
   if r.returncode:print(name,r.returncode,r.stdout,flush=True);raise SystemExit(r.returncode)
   d=json.loads((out/f'{name}.json').read_text());assert len(d['requests'])==a.repeats
   print(name,[x['total_inference_s'] for x in d['requests']],f"rss_mib={d['peak_rss_mib']:.2f} gpu_delta_mib={d['peak_gpu_device_delta_mib']}",flush=True)
